async function main_page() {
    window.wde = set_wde();
    set_time_now();
    write_secelt_time('Start');
    write_secelt_time('End');
    await updateProgress(65);

    window.speeds = [0.1, 1, 2, 4, 8, 15, 30, 60, 120, 240, 600];
    write_secelt_speed();
    await updateProgress(70);
    window.is_lines = {};
    write_secelt_lines();
    await updateProgress(80);
    count_lines();
    await updateProgress(90);
    //set_size('m');
    window.is_hide_linename = false;
    window.is_hide_stationname = false;
    window.is_hide_station = false;

    //draw_map(is_hide_station, is_hide_linename, is_hide_stationname);
    svg_init_xy();
    await updateProgress(100);
    //hide_loading();
    window.is_loop = false;
    window.is_auto = true;

    window.is_pause = false;
    window.is_play = false;
    apply_link(window.location.href);

    window.link = '';
    window.tips_now = 0;
    change_tips(tips_now);
    window.size_text = 'm';

    window.is_mobile = window.screen.width <= 768;
    change_detail();
    window.now_minute = NaN;
    window.thumb_info = {
        'is_drag': false,
        'start_y': NaN,
        'goingto': NaN,
        'ratio': NaN,
        'table_id': '',
    };
    window.mouse_start = null;
    window.timer_follow = null;  // 用于跟踪train的计时器
    document.getElementById('link').addEventListener('click', function (e) {
        e.preventDefault();
        this.select();
    });
    bind_event_detail();
    if (is_auto) start();
}

//侧边栏展开与关闭
function open_siderbar() {
    document.getElementById('sider-bar').style.left = '0px';
    for (let each of document.getElementsByClassName('side-2l'))
        each.style.height = '48px';
    for (let each of document.getElementsByClassName('side-l'))
        each.getElementsByTagName('i')[0].style.paddingRight = '16px';
}
function close_siderbar() {
    document.getElementById('sider-bar').style.left = '-178px';
    for (let each of document.getElementsByClassName('side-2l'))
        each.style.height = '24px';
    for (let each of document.getElementsByClassName('side-l'))
        each.getElementsByTagName('i')[0].style.paddingRight = '11px';
}
function invert_siderbar() {
    if (document.getElementById("sider-bar").style.left === '0px')
        close_siderbar();
    else
        open_siderbar();
}

function to02d(i) {
    let s = i.toString();
    if (s.length === 1) {
        s = '0' + s;
    }
    return s;
}

function change_auto(option) {
    if (option !== undefined) is_auto = !!option;
    else is_auto = !is_auto;
    if (is_auto) document.getElementById('btn_auto').className = 'side-2l2-btn btn-selected';
    else document.getElementById('btn_auto').className = 'side-2l2-btn btn-unselected';
}

function change_loop(option) {
    if (option !== undefined) is_loop = !!option;
    else is_loop = !is_loop;
    if (is_loop) document.getElementById('btn_loop').className = 'side-2l2-btn btn-selected';
    else document.getElementById('btn_loop').className = 'side-2l2-btn btn-unselected';
}

function set_wde(wde) {
    if (wde !== 'wd' && wde !== 'we') {
        const d = new Date();
        if (d.getDay() == 0 || d.getDay() == 6) wde = 'we';
        else wde = 'wd';
    }
    if (wde === 'wd') {
        //window.wde = 'wd';
        document.getElementById('btn_wd').className = 'side-2l2-btn btn-selected';
        document.getElementById('btn_we').className = 'side-2l2-btn btn-unselected';
    }
    else if (wde === 'we') {
        //window.wde = 'we';
        document.getElementById('btn_we').className = 'side-2l2-btn btn-selected';
        document.getElementById('btn_wd').className = 'side-2l2-btn btn-unselected';
    }
    return wde;
}
function set_size(size) {
    document.getElementById('btn_size_l').className = 'side-2l2-btn btn-unselected';
    document.getElementById('btn_size_m').className = 'side-2l2-btn btn-unselected';
    document.getElementById('btn_size_s').className = 'side-2l2-btn btn-unselected';
    document.getElementById('btn_size_xs').className = 'side-2l2-btn btn-unselected';
    if (size === 'l') {
        window.train_size = 4;
        document.getElementById('btn_size_l').className = 'side-2l2-btn btn-selected';
    }
    else if (size === 'm') {
        window.train_size = 3;
        document.getElementById('btn_size_m').className = 'side-2l2-btn btn-selected';
    }
    else if (size === 's') {
        window.train_size = 2;
        document.getElementById('btn_size_s').className = 'side-2l2-btn btn-selected';
    }
    else if (size === 'xs') {
        window.train_size = 1;
        document.getElementById('btn_size_xs').className = 'side-2l2-btn btn-selected';
    }
    else if (parseFloat(size)) {
        window.train_size = parseFloat(size);
    }
    else {
        window.train_size = 3;
        document.getElementById('btn_size_m').className = 'side-2l2-btn btn-selected';
    }
    window.size_text = size;
    let t = window.train_size;
    //let points = `0,0 ${t * 3},0 ${t},${t * 2} -${t * 3},${t * 2} -${t * 3},0`;
    let points = `${t},0 ${t * 7},0 ${t * 5},${t * 2} ${t},${t * 2}`;
    window.xml_symbol = `<polygon class="train" points="${points}" stroke-width="${t / 2}" stroke="#000000" />`;
    d3.select('#train')
        .attr('x', -t * 4)
        .attr('refX', t * 4)
        .html(window.xml_symbol);
}
