function count_lines() {
    let num_lines = 0;
    let num_direct = 0;
    for (let line_name in is_lines) {
        let t = false;
        for (let direct in is_lines[line_name]) {
            if (is_lines[line_name][direct]) {
                num_direct++;
                t = true;
            }
        }
        if (t) {
            num_lines++;
        }
    }
    document.getElementById('countDirect').innerText = num_direct;
    document.getElementById('countLines').innerText = num_lines;
}
function refresh_lines() {
    /*按钮重置*/
    const btns = document.getElementsByClassName('popup-btn');
    for (let btn of btns) {
        btn.className = 'popup-btn btn-unselected';
    }
    const div_lines = document.getElementById('selectLines');
    set_scroll_lines_opacity_by_div(div_lines);
    for (let i = 0; i < Object.keys(is_lines).length; i++) {
        let line_name = Object.keys(is_lines)[i];
        let t = false;
        for (let j = 0; j < Object.keys(is_lines[line_name]).length; j++) {
            let direct = Object.keys(is_lines[line_name])[j];
            if (is_lines[line_name][direct]) {
                t = true;
                //div_lines.childNodes[i].childNodes[j + 1].style = 'background-color: ' + line_colors[line_name] + '; color: #ffffff;';
                div_lines.childNodes[i].childNodes[j + 1].style['background-color'] = line_colors[line_name];
                div_lines.childNodes[i].childNodes[j + 1].style['color'] = '#ffffff';
            }
            else {
                div_lines.childNodes[i].childNodes[j + 1].style['background-color'] = null;
                div_lines.childNodes[i].childNodes[j + 1].style['color'] = null;
            }
        }
        if (t) {
            div_lines.childNodes[i].childNodes[0].style['background-color'] = line_colors[line_name];
            div_lines.childNodes[i].childNodes[0].style['color'] = '#ffffff';
        }
        else {
            div_lines.childNodes[i].childNodes[0].style['background-color'] = null;
            div_lines.childNodes[i].childNodes[0].style['color'] = null;
        }
    }
}
function invert_line(line_name, direct) {
    if (direct) {
        is_lines[line_name][direct] = !is_lines[line_name][direct];
    }
    else {
        let ts = Object.values(is_lines[line_name]);
        let t = ts[0] || ts[1];
        for (let each_direct in is_lines[line_name]) {
            is_lines[line_name][each_direct] = !t;
        }
    }
    refresh_lines();
}
function select_lines(this_btn, action) {
    if (action === 'ok') {
        document.getElementById('selectLinesContent').style = 'display: none;';
        count_lines();
        return;
    }
    else if (action === 'all') {
        for (let line_name in is_lines) {
            for (let direct in is_lines[line_name]) {
                is_lines[line_name][direct] = true;
            }
        }
    }
    else if (action === 'invert') {
        for (let line_name in is_lines) {
            for (let direct in is_lines[line_name]) {
                is_lines[line_name][direct] = !is_lines[line_name][direct];
            }
        }
    }
    else if (action === 'none') {
        for (let line_name in is_lines) {
            for (let direct in is_lines[line_name]) {
                is_lines[line_name][direct] = false;
            }
        }
    }
    refresh_lines();
    if (this_btn) this_btn.className = 'popup-btn btn-selected';
}
function change_tips(opcode) {
    if (parseInt(opcode)) tips_now = parseInt(opcode);
    else if (opcode == 'next') tips_now += 1;
    else if (opcode == 'prev') tips_now += tips.length - 1;
    tips_now %= tips.length;
    document.getElementById('tips_content').innerHTML = tips[tips_now];
    document.getElementById('tips_now').innerHTML = tips_now + 1;
    document.getElementById('tips_total').innerHTML = tips.length;
}
